-- QueryCraft synthetic university database (SQLite).
-- All data is synthetic (generated by data/generate_db.py, Faker seed 42).

PRAGMA foreign_keys = ON;

CREATE TABLE programs (
    program_id      INTEGER PRIMARY KEY,
    program_name    TEXT    NOT NULL UNIQUE,
    department      TEXT    NOT NULL,
    duration_years  INTEGER NOT NULL
);

CREATE TABLE hostels (
    hostel_id    INTEGER PRIMARY KEY,
    hostel_name  TEXT    NOT NULL UNIQUE,
    gender       TEXT    NOT NULL CHECK (gender IN ('M', 'F')),
    capacity     INTEGER NOT NULL
);

CREATE TABLE students (
    student_id      INTEGER PRIMARY KEY,
    name            TEXT    NOT NULL,
    gender          TEXT    NOT NULL CHECK (gender IN ('M', 'F')),
    program_id      INTEGER NOT NULL REFERENCES programs(program_id),
    admission_year  INTEGER NOT NULL,
    current_year    INTEGER NOT NULL,
    hostel_id       INTEGER REFERENCES hostels(hostel_id),   -- NULL = day scholar
    email           TEXT    NOT NULL UNIQUE
);

CREATE TABLE courses (
    course_id    INTEGER PRIMARY KEY,
    course_code  TEXT    NOT NULL UNIQUE,
    course_name  TEXT    NOT NULL,
    program_id   INTEGER NOT NULL REFERENCES programs(program_id),
    semester     INTEGER NOT NULL,
    credits      INTEGER NOT NULL
);

CREATE TABLE enrollments (
    enrollment_id  INTEGER PRIMARY KEY,
    student_id     INTEGER NOT NULL REFERENCES students(student_id),
    course_id      INTEGER NOT NULL REFERENCES courses(course_id),
    academic_year  TEXT    NOT NULL,           -- e.g. '2026-27'
    UNIQUE (student_id, course_id)
);

CREATE TABLE attendance (
    enrollment_id     INTEGER PRIMARY KEY REFERENCES enrollments(enrollment_id),
    classes_held      INTEGER NOT NULL,
    classes_attended  INTEGER NOT NULL CHECK (classes_attended <= classes_held)
);

CREATE TABLE exam_results (
    enrollment_id   INTEGER PRIMARY KEY REFERENCES enrollments(enrollment_id),
    internal_marks  INTEGER NOT NULL,          -- out of 40
    external_marks  INTEGER NOT NULL,          -- out of 60
    grade           TEXT    NOT NULL CHECK (grade IN ('O','A+','A','B+','B','C','P','F'))
);

CREATE TABLE fees (
    fee_id         INTEGER PRIMARY KEY,
    student_id     INTEGER NOT NULL REFERENCES students(student_id),
    academic_year  TEXT    NOT NULL,
    amount_due     INTEGER NOT NULL,           -- rupees
    amount_paid    INTEGER NOT NULL,           -- rupees
    due_date       TEXT    NOT NULL,           -- ISO date 'YYYY-MM-DD'
    status         TEXT    NOT NULL CHECK (status IN ('PAID','PARTIAL','UNPAID')),
    UNIQUE (student_id, academic_year)
);
